presets.css:
/* ===== 由「气泡生成器」导出 · 贴到对话主题 A 区 ===== */
.chat-thread {
  /* 顶栏胶囊 */
  --dress-header-bg: rgba(227, 255, 228, 1.000);
  --dress-header-blur: 4px;
  --dress-header-border: rgba(255, 255, 255, 0.350);
  --dress-header-radius: 25px;
  --dress-header-shadow: 0 9px 27px rgba(0, 0, 0, 0.094);
  --dress-header-title-color: #1a1a1a;
  --dress-header-title-size: 15px;
  --dress-header-title-weight: 500;
  --dress-header-icon-color: #1a1a1a;

  /* 我方气泡 */
  --dress-bubble-me-bg: #deffe9;
  --dress-bubble-me-fg: #1a1a1a;
  --dress-bubble-me-border: 2px solid #ffffff;
  --dress-bubble-me-shadow: 0 2px 10px rgba(0, 0, 0, 0.070);
  --dress-bubble-me-radius: 2px;

  /* 对方气泡 */
  --dress-bubble-them-bg: #ffffff;
  --dress-bubble-them-bg-gradient: linear-gradient(80deg, #ffffff, #d3f5ce);
  --dress-bubble-them-fg: #1a1a1a;
  --dress-bubble-them-border: none;
  --dress-bubble-them-shadow: 0 2px 8px rgba(230, 230, 230, 0.060);
  --dress-bubble-them-radius: 10px;

  /* 输入胶囊 */
  --dress-compose-bar-bg: rgba(211, 255, 199, 0.610);
  --dress-compose-bar-fg: #1a1a1a;
  --dress-compose-bar-radius: 25px;
  --dress-compose-bar-border: 1px solid rgba(0, 0, 0, 0.060);
  --dress-compose-bar-shadow: none;
  --dress-compose-bar-blur: blur(10px);

  /* 其他 */
  --dress-timestamp-color: #9aa2b2;
}

/* ===== 气泡贴纸 · 把这段一起贴到 E 区 ===== */
.chat-msg.is-me .chat-bubble { position: relative; }
.chat-msg.is-me .chat-bubble::after {
  content: '';
  position: absolute;
  bottom: -10px;
  right: -10px;
  width: 27px;
  height: 27px;
  background: url("https://file.zhuyitai.com/feedback/202610/b0617193b7c21fdfbc5f9cfc9f822f22.png") center / contain no-repeat;
  transform: translate(0px, -4px) rotate(7deg);
  pointer-events: none;
  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, .15));
}

.chat-msg.is-them .chat-bubble { position: relative; }
.chat-msg.is-them .chat-bubble::after {
  content: '';
  position: absolute;
  bottom: -10px;
  left: -10px;
  width: 26px;
  height: 26px;
  background: url("https://oss-chat-bucket.oss-cn-beijing.aliyuncs.com/picture/console/chatres/7fd101e440d84afa8608480893e72180tEHDdnsl.png") center / contain no-repeat;
  transform: translate(0px, 2px) rotate(0deg);
  pointer-events: none;
  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, .15));
}
